const req = $('Dashboard: warehouse action').first().json.body || {};
const p = req.params || {};
const who = $('Verify caller').first().json;
const role = who.role;
const actor = 'dashboard:' + who.userId;
const senior = ['admin', 'manager'].includes(role);
const bad = (error, code = 400) => [{ json: { valid: false, code, error } }];
const ok = (rpc, body, note) => [{ json: { valid: true, rpc, body, note } }];
const s = (v) => String(v == null ? '' : v).trim();
switch (req.action) {
  case 'suggest_bin':
    if (!p.order_id) return bad('An order is required.');
    return ok('flow_wh_suggest_bin', { p_order: p.order_id, p_units: p.units ? Number(p.units) : null }, '');
  case 'assign_bin':
    if (!p.order_id || !s(p.bin_code)) return bad('Choose an order and a bin.');
    if (p.override && !senior) return bad('Only a manager or admin can override a bin rule.', 403);
    return ok('flow_wh_assign_bin', { p_order: p.order_id, p_bin_code: s(p.bin_code), p_units: Number(p.units), p_actor: actor, p_override: !!p.override, p_reason: s(p.reason) || null, p_lines: p.lines || null }, 'Order put away. The bin and order history are updated.');
  case 'move_order':
    if (!p.order_id || !s(p.from_bin) || !s(p.to_bin)) return bad('Choose the order, the bin it is in and the bin to move it to.');
    if (p.override && !senior) return bad('Only a manager or admin can override a bin rule.', 403);
    return ok('flow_wh_move_order', { p_order: p.order_id, p_from: s(p.from_bin), p_to: s(p.to_bin), p_actor: actor, p_override: !!p.override, p_reason: s(p.reason) || null }, 'Order moved and both bins updated.');
  case 'release_bin':
    if (!s(p.bin_code)) return bad('Choose a bin.');
    return ok('flow_wh_release_bin', { p_bin_code: s(p.bin_code), p_order: p.order_id || null, p_actor: actor, p_reason: s(p.reason) }, 'Bin released. History is kept.');
  case 'set_bin_status':
    if (!s(p.bin_code)) return bad('Choose a bin.');
    if (s(p.status) === 'retired' && !senior) return bad('Only a manager or admin can retire a bin.', 403);
    return ok('flow_wh_set_bin_status', { p_bin_code: s(p.bin_code), p_status: s(p.status), p_actor: actor, p_reason: s(p.reason) }, 'Bin status updated.');
  case 'create_bins':
    if (!['admin', 'manager', 'warehouse'].includes(role)) return bad('Your role cannot create bins.', 403);
    return ok('flow_wh_create_bins', { p_zone: s(p.zone), p_prefix: s(p.prefix), p_count: Number(p.count), p_type: s(p.location_type) || 'bin_bay', p_capacity: p.capacity ? Number(p.capacity) : null, p_actor: actor }, 'Bins created. Print their labels from the Labels page.');
  case 'set_stock_location':
    if (!s(p.sku)) return bad('A SKU is required.');
    return ok('flow_wh_set_stock_location', { p_sku: s(p.sku), p_location: s(p.location), p_actor: actor }, 'Stock location saved.');
  case 'generate_order_labels':
    if (!p.order_id) return bad('An order is required.');
    return ok('flow_wh_generate_order_labels', { p_order: p.order_id, p_actor: actor, p_include_dispatch: !!p.include_dispatch }, 'Labels generated. They are waiting in the Labels page to be printed.');
  case 'generate_labels':
    if (!s(p.type) || !Array.isArray(p.refs)) return bad('Choose a label type and what to label.');
    return ok('flow_wh_generate_labels_batch', { p_type: s(p.type), p_refs: p.refs.map(s), p_actor: actor }, 'Labels generated. They are waiting in the Labels page to be printed.');
  case 'mark_printed':
    if (!Array.isArray(p.codes) || !p.codes.length) return bad('No labels selected.');
    return ok('flow_wh_mark_printed', { p_codes: p.codes.map(s), p_actor: actor, p_reason: s(p.reason) || null, p_format: s(p.format) || 'A4', p_copies: p.copies ? Number(p.copies) : 1 }, 'Print recorded in the audit trail.');
  case 'print_failed':
    if (!Array.isArray(p.codes) || !p.codes.length) return bad('No labels selected.');
    return ok('flow_wh_mark_print_failed', { p_codes: p.codes.map(s), p_actor: actor, p_reason: s(p.reason) || null }, 'Marked as failed to print; they stay in the awaiting-print list.');
  default:
    return bad('Unknown action.');
}
